// Курс Lua для Roblox — СОБРАН АВТОМАТИЧЕСКИ из courses/lua/ (node scripts/build-course.js). Не править вручную.
(function (root) {
  const UNITS = {"lang":"lua","units":[{"id":"lua-u1","title":"Раздел 1. Первые шаги в Lua","lessons":[{"id":"lua-l1","title":"Привет, print!","emoji":"👋","intro":"В Roblox Studio скрипты пишут на <b>Luau</b> — это Lua с улучшениями. Вывод: <code>print(\"текст\")</code>. В Roblox текст появляется в окне Output.","questions":[{"type":"choice","q":"Какая команда выводит текст в Lua?","options":["print()","console.log()","echo()","say()"],"explain":"В Lua, как и в Python, — print."},{"type":"output","q":"Что выведет код?","code":"print(\"Привет, Roblox!\")","options":["Привет, Roblox!","\"Привет, Roblox!\"","print","Ничего"],"explain":"Кавычки не печатаются."},{"type":"output","q":"Что выведет код?","code":"print(10 + 5)","options":["15","10 + 5","105","Ошибку"],"explain":"Числа складываются."},{"type":"output","q":"Склеивание строк в Lua — две точки. Что выведет код?","code":"print(\"Игрок\" .. \"123\")","options":["Игрок123","Игрок 123","Игрок + 123","Ошибку"],"explain":".. склеивает строки (в других языках это +)."},{"type":"choice","q":"Как пишут комментарий в Lua?","options":["-- комментарий","# комментарий","// комментарий","/* комментарий"],"explain":"Комментарий в Lua начинается с двух минусов."},{"type":"input","q":"Допиши оператор склеивания строк:","code":"print(\"Монеты: \" ___ 50)","answers":[".."],"explain":"Две точки склеивают текст и число."}]},{"id":"lua-l2","title":"Переменные: local","emoji":"📦","intro":"Переменные в Lua объявляют словом <code>local</code>: <code>local coins = 0</code>. В Roblox почти всегда пишут local — так скрипты работают быстрее и не мешают друг другу.","questions":[{"type":"output","q":"Что выведет код?","code":"local coins = 10\ncoins = coins + 5\nprint(coins)","options":["15","10","105","Ошибку"],"explain":"10 + 5 = 15."},{"type":"output","q":"Что выведет код?","code":"local name = \"Ярик\"\nprint(\"Привет, \" .. name)","options":["Привет, Ярик","Привет, name","Привет, .. name","Ошибку"],"explain":"Подставилось значение переменной."},{"type":"output","q":"Пустое значение в Lua — nil. Что выведет код?","code":"local x\nprint(x)","options":["nil","0","Ошибку","Ничего"],"explain":"Переменная без значения хранит nil — «ничего»."},{"type":"choice","q":"Как в Lua написать «истина»?","options":["true","True","TRUE","yes"],"explain":"Логические значения пишутся маленькими буквами: true и false."},{"type":"output","q":"Длина строки — решётка #. Что выведет код?","code":"print(#\"Roblox\")","options":["6","5","Roblox","Ошибку"],"explain":"# возвращает длину: в Roblox 6 букв."},{"type":"input","q":"Объяви локальную переменную:","code":"___ health = 100","answers":["local"],"explain":"local — локальная переменная."}]},{"id":"lua-l3","title":"Условия: if then end","emoji":"🔀","intro":"Условие в Lua: <code>if условие then ... elseif ... else ... end</code>. Блоки закрываются словом <code>end</code>. «Не равно» — <code>~=</code>.","questions":[{"type":"output","q":"Что выведет код?","code":"local health = 0\nif health > 0 then\n  print(\"Жив\")\nelse\n  print(\"Респаун...\")\nend","options":["Респаун...","Жив","Жив Респаун...","Ошибку"],"explain":"0 > 0 — неверно, сработал else."},{"type":"output","q":"Что выведет код?","code":"print(5 ~= 3)","options":["true","false","2","Ошибку"],"explain":"~= — «не равно». 5 не равно 3 — true."},{"type":"output","q":"Что выведет код?","code":"local coins = 120\nif coins >= 100 then\n  print(\"Купил меч!\")\nelseif coins >= 50 then\n  print(\"Купил щит\")\nelse\n  print(\"Мало монет\")\nend","options":["Купил меч!","Купил щит","Мало монет","Купил меч! Купил щит"],"explain":"120 ≥ 100 — сработала первая ветка, остальные пропущены."},{"type":"bug","q":"Чего не хватает?","code":"if coins > 10 then\n  print(\"Богач\")","options":["end в конце","then","скобок","Ошибки нет"],"explain":"Каждый if закрывается словом end."},{"type":"choice","q":"Как в Lua пишется «и» в условии?","options":["and","&&","&","и"],"explain":"В Lua логика словами: and, or, not."},{"type":"input","q":"Допиши «не равно» в Lua:","code":"if team ___ \"Красные\" then","answers":["~="],"explain":"В Lua «не равно» — ~=."}]},{"id":"lua-p1","title":"Практика: первые скрипты","emoji":"💻","intro":"Теперь пишешь код сам! Нажимай <b>▶️ Запустить</b>, чтобы посмотреть результат, и <b>Проверить</b> — чтобы Питоша прогнал тесты. Это обычный Lua — на нём основан Luau, язык скриптов Roblox.","questions":[{"type":"code","q":"Первый скрипт","task":"Выведи фразу: <code>Привет, Roblox!</code>","starter":"-- напиши код здесь\n","tests":[{"out":"Привет, Roblox!"}],"hint":"Используй <code>print(\"...\")</code>.","solution":"print(\"Привет, Roblox!\")","explain":"print выводит текст."},{"type":"code","q":"Награда за уровень","task":"Скрипт получает номер уровня (через <code>io.read()</code>) и выводит награду: уровень × 10 монет. Формат: <code>Монеты: 30</code>","starter":"local level = tonumber(io.read())\n","tests":[{"stdin":"3","out":"Монеты: 30"},{"stdin":"10","out":"Монеты: 100"}],"hint":"tonumber превращает текст в число. Склей: <code>\"Монеты: \" .. level * 10</code>.","solution":"local level = tonumber(io.read())\nprint(\"Монеты: \" .. level * 10)","explain":"Сначала умножение, потом склеивание."},{"type":"code","q":"Хватит ли монет?","task":"Скрипт получает число монет. Если их 100 или больше — выведи <code>Можно купить</code>, иначе <code>Копи дальше</code>.","starter":"local coins = tonumber(io.read())\n","tests":[{"stdin":"150","out":"Можно купить"},{"stdin":"100","out":"Можно купить"},{"stdin":"20","out":"Копи дальше"}],"hint":"<code>if coins >= 100 then ... else ... end</code>","solution":"local coins = tonumber(io.read())\nif coins >= 100 then\n  print(\"Можно купить\")\nelse\n  print(\"Копи дальше\")\nend","explain":"Не забудь end в конце условия."}]}]},{"id":"lua-u2","title":"Раздел 2. Строки","lessons":[{"id":"lua-l4","title":"Склейка и длина","emoji":"🔤","intro":"Строки склеивают двумя точками: <code>\"Hi, \" .. name</code>. Длина строки — решётка: <code>#name</code>. Числа при склейке превращаются в текст сами: <code>\"Очки: \" .. 10</code>. Число из текста — <code>tonumber(\"5\")</code>, текст из числа — <code>tostring(5)</code>.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local name = \"Robloxian\"\nprint(\"Привет, \" .. name)","options":["Привет, Robloxian","Привет, .. name","Привет,Robloxian","Ошибку"],"explain":".. склеивает строки."},{"type":"output","q":"Что выведет скрипт?","code":"print(#\"Roblox\")","options":["6","5","7","Roblox"],"explain":"# — длина."},{"type":"output","q":"Что выведет скрипт?","code":"print(\"Монеты: \" .. 5 * 2)","options":["Монеты: 10","Монеты: 5 * 2","Монеты: 52","Ошибку"],"explain":"Сначала умножение, потом склейка."},{"type":"output","q":"Что выведет скрипт?","code":"print(tonumber(\"7\") + 3)","options":["10","73","Ошибку","nil"],"explain":"tonumber превратил строку в число."},{"type":"bug","q":"Где ошибка?","code":"print(\"Уровень \" + 5)","options":["В Lua строки склеивают через .., а не +","Нужны одинарные кавычки","Нельзя 5","Ошибки нет"],"explain":"+ в Lua — только для чисел."},{"type":"input","q":"Оператор склейки строк в Lua","answers":[".."],"explain":".."}]},{"id":"lua-l5","title":"Функции строк","emoji":"🛠️","intro":"<code>string.upper(s)</code> или <code>s:upper()</code> — БОЛЬШИМИ, <code>s:lower()</code> — маленькими, <code>s:sub(1, 3)</code> — кусок (нумерация с 1!), <code>s:rep(3)</code> — повторить, <code>s:reverse()</code> — перевернуть, <code>s:find(\"x\")</code> — найти позицию.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"print((\"noob\"):upper())","options":["NOOB","noob","Noob","Ошибку"],"explain":"upper — все буквы большие."},{"type":"output","q":"Что выведет скрипт?","code":"local s = \"Roblox\"\nprint(s:sub(1, 3))","options":["Rob","obl","Ro","Robl"],"explain":"В Lua нумерация с 1, и конец включается."},{"type":"output","q":"Что выведет скрипт?","code":"print((\"ab\"):rep(3))","options":["ababab","ab3","ab ab ab","aaabbb"],"explain":"rep повторяет строку."},{"type":"output","q":"Что выведет скрипт?","code":"print((\"abc\"):reverse())","options":["cba","abc","bca","Ошибку"],"explain":"reverse переворачивает."},{"type":"output","q":"Что выведет скрипт?","code":"print((\"hello\"):find(\"l\"))","options":["3 3","2","4","true"],"explain":"find возвращает начало и конец найденного — два числа."},{"type":"input","q":"С какого номера начинается нумерация символов в Lua?","answers":["1"],"explain":"В Lua всё считается с 1."}]},{"id":"lua-l6","title":"Форматирование","emoji":"🎨","intro":"<code>string.format(\"%s набрал %d очков\", name, score)</code>: <code>%s</code> — строка, <code>%d</code> — целое, <code>%.2f</code> — дробное с 2 знаками. Деление <code>/</code> в Lua всегда даёт дробь (<code>10/2 = 5.0</code>), целочисленное — <code>//</code>, остаток — <code>%</code>.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"print(string.format(\"%s: %d\", \"Очки\", 50))","options":["Очки: 50","%s: %d","Очки 50","Ошибку"],"explain":"Подстановка по порядку."},{"type":"output","q":"Что выведет скрипт?","code":"print(string.format(\"%.1f\", 3.14159))","options":["3.1","3.14","3","3.14159"],"explain":"Один знак после точки."},{"type":"output","q":"Что выведет скрипт?","code":"print(10 / 2)","options":["5.0","5","2","Ошибку"],"explain":"Обычное деление в Lua 5.3 всегда даёт дробное число."},{"type":"output","q":"Что выведет скрипт?","code":"print(7 // 2)","options":["3","3.5","4","Ошибку"],"explain":"// — целочисленное деление."},{"type":"output","q":"Что выведет скрипт?","code":"print(17 % 5)","options":["2","3","3.4","17"],"explain":"Остаток от деления."},{"type":"input","q":"Какой код в string.format для целого числа?","answers":["%d"],"explain":"%d"}]},{"id":"lua-p2","title":"Практика: строки","emoji":"💻","intro":"Пишешь скрипт сам! <b>▶️ Запустить</b> — посмотреть, <b>Проверить</b> — прогнать тесты.","questions":[{"type":"code","q":"Табличка игрока","task":"Скрипт получает имя. Выведи <code>[VIP] ИМЯ</code> (имя большими буквами).","starter":"local name = io.read()\n","tests":[{"stdin":"yar","out":"[VIP] YAR"},{"stdin":"Builder","out":"[VIP] BUILDER"}],"hint":"<code>\"[VIP] \" .. name:upper()</code>","solution":"local name = io.read()\nprint(\"[VIP] \" .. name:upper())","explain":"Такие таблички над головой делают в Roblox."},{"type":"code","q":"Полоска здоровья","task":"Скрипт получает здоровье от 0 до 10. Выведи столько символов <code>#</code>, сколько здоровья, и потом <code>-</code> до 10 символов.","starter":"local hp = tonumber(io.read())\n","tests":[{"stdin":"7","out":"#######---"},{"stdin":"10","out":"##########"},{"stdin":"0","out":"----------"}],"hint":"<code>(\"#\"):rep(hp) .. (\"-\"):rep(10 - hp)</code>","solution":"local hp = tonumber(io.read())\nprint((\"#\"):rep(hp) .. (\"-\"):rep(10 - hp))","explain":"Так рисуют полоски в текстовых играх."},{"type":"code","q":"Средний счёт","task":"Скрипт получает два целых числа (по одному в строке). Выведи их среднее с одним знаком после точки.","starter":"local a = tonumber(io.read())\nlocal b = tonumber(io.read())\n","tests":[{"stdin":"3\n4","out":"3.5"},{"stdin":"10\n10","out":"10.0"}],"hint":"<code>string.format(\"%.1f\", (a + b) / 2)</code>","solution":"local a = tonumber(io.read())\nlocal b = tonumber(io.read())\nprint(string.format(\"%.1f\", (a + b) / 2))","explain":"string.format — аккуратный вывод чисел."}]}]},{"id":"lua-u3","title":"Раздел 3. Условия и логика","lessons":[{"id":"lua-l7","title":"if, elseif, else","emoji":"🔀","intro":"<code>if hp &gt; 50 then ... elseif hp &gt; 0 then ... else ... end</code>. Обрати внимание: <code>elseif</code> пишется слитно, а в конце всегда <code>end</code>. Сравнения: <code>==</code>, <code>~=</code>, <code>&lt;</code>, <code>&gt;</code>, <code>&lt;=</code>, <code>&gt;=</code>.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local hp = 30\nif hp > 50 then\n  print(\"бодр\")\nelseif hp > 0 then\n  print(\"ранен\")\nelse\n  print(\"выбыл\")\nend","options":["ранен","бодр","выбыл","Ошибку"],"explain":"30 не больше 50, но больше 0."},{"type":"bug","q":"Где ошибка?","code":"if coins > 10 then\n  print(\"богач\")\nelse if coins > 0 then\n  print(\"есть немного\")\nend","options":["elseif пишется слитно","Нужно == ","Нельзя print","Ошибки нет"],"explain":"«else if» откроет новое if, которому не хватит end."},{"type":"output","q":"Что выведет скрипт?","code":"print(5 ~= 5)","options":["false","true","nil","Ошибку"],"explain":"~= — не равно. 5 равно 5."},{"type":"output","q":"Что выведет скрипт?","code":"print(\"5\" == 5)","options":["false","true","Ошибку","nil"],"explain":"Строка и число в Lua не равны."},{"type":"choice","q":"Чем заканчивается любой if в Lua?","options":["end","}","endif","fi"],"explain":"Блоки в Lua закрываются словом end."},{"type":"input","q":"Допиши слово после условия:","code":"if score > 100 ___","answers":["then"],"explain":"if ... then"}]},{"id":"lua-l8","title":"and, or, not","emoji":"🧠","intro":"<code>and</code> — оба верны, <code>or</code> — хотя бы одно, <code>not</code> — наоборот. В Lua ложны только <code>false</code> и <code>nil</code>, а <b>0 и пустая строка — истинны</b>! Трюк для значения по умолчанию: <code>local name = input or \"Гость\"</code>.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local level, vip = 10, true\nprint(level >= 10 and vip)","options":["true","false","10","nil"],"explain":"Оба верны."},{"type":"output","q":"Что выведет скрипт?","code":"if 0 then print(\"да\") else print(\"нет\") end","options":["да","нет","Ошибку","0"],"explain":"В Lua 0 — истинное значение (в отличие от Python и JS)!"},{"type":"output","q":"Что выведет скрипт?","code":"local nick = nil\nprint(nick or \"Гость\")","options":["Гость","nil","false","Ошибку"],"explain":"nil ложный — берётся вторая часть."},{"type":"output","q":"Что выведет скрипт?","code":"print(not nil)","options":["true","false","nil","Ошибку"],"explain":"not nil = true."},{"type":"output","q":"Что выведет скрипт?","code":"local n = 7\nprint(n > 0 and n % 2 == 0)","options":["false","true","7","nil"],"explain":"7 нечётное."},{"type":"input","q":"Что в Lua означает «ничего, пустое значение»?","answers":["nil"],"explain":"nil"}]},{"id":"lua-l9","title":"Локальные переменные","emoji":"📍","intro":"Всегда пиши <code>local</code>: <code>local coins = 0</code>. Без local переменная становится <b>глобальной</b> — её видно везде, и легко сломать что-то случайно. Переменная, объявленная внутри блока (if, for, function), видна только в нём.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local x = 1\nif true then\n  local x = 2\nend\nprint(x)","options":["1","2","nil","Ошибку"],"explain":"Внутри if — своя x."},{"type":"output","q":"Что выведет скрипт?","code":"if true then\n  local secret = 42\nend\nprint(secret)","options":["nil","42","Ошибку","true"],"explain":"Снаружи блока secret не видна — nil."},{"type":"output","q":"Что выведет скрипт?","code":"local a, b = 3, 4\nprint(a + b)","options":["7","34","3","Ошибку"],"explain":"Можно объявить несколько переменных сразу."},{"type":"output","q":"Что выведет скрипт? (обмен значений)","code":"local a, b = 1, 2\na, b = b, a\nprint(a, b)","options":["2 1","1 2","2 2","Ошибку"],"explain":"Так в Lua меняют значения местами. print разделяет значения табуляцией."},{"type":"choice","q":"Почему в Roblox советуют всегда писать local?","options":["Глобальные переменные медленнее и легко ломаются","Без local не работает","Так красивее","Не советуют"],"explain":"local — быстрее и безопаснее."},{"type":"input","q":"Слово для объявления локальной переменной","answers":["local"],"explain":"local"}]},{"id":"lua-p3","title":"Практика: условия","emoji":"💻","intro":"Скрипты, которые принимают решения.","questions":[{"type":"code","q":"Ранг игрока","task":"Скрипт получает опыт. Выведи ранг: от 1000 — <code>Легенда</code>, от 500 — <code>Профи</code>, от 100 — <code>Игрок</code>, иначе <code>Новичок</code>.","starter":"local xp = tonumber(io.read())\n","tests":[{"stdin":"1500","out":"Легенда"},{"stdin":"500","out":"Профи"},{"stdin":"150","out":"Игрок"},{"stdin":"5","out":"Новичок"}],"hint":"if ... elseif ... elseif ... else ... end","solution":"local xp = tonumber(io.read())\nif xp >= 1000 then\n  print(\"Легенда\")\nelseif xp >= 500 then\n  print(\"Профи\")\nelseif xp >= 100 then\n  print(\"Игрок\")\nelse\n  print(\"Новичок\")\nend","explain":"Проверяем от большего к меньшему."},{"type":"code","q":"Вход в зону","task":"Скрипт получает уровень и есть ли пропуск (<code>да</code>/<code>нет</code>). Вход открыт, если уровень от 10 <b>или</b> есть пропуск. Выведи <code>Проходи</code> или <code>Закрыто</code>.","starter":"local level = tonumber(io.read())\nlocal pass = io.read()\n","tests":[{"stdin":"12\nнет","out":"Проходи"},{"stdin":"3\nда","out":"Проходи"},{"stdin":"3\nнет","out":"Закрыто"}],"hint":"<code>if level >= 10 or pass == \"да\" then</code>","solution":"local level = tonumber(io.read())\nlocal pass = io.read()\nif level >= 10 or pass == \"да\" then\n  print(\"Проходи\")\nelse\n  print(\"Закрыто\")\nend","explain":"or — хотя бы одно условие."},{"type":"code","q":"Чётный или нет","task":"Скрипт получает целое число. Выведи <code>чёт</code> или <code>нечет</code>.","starter":"local n = tonumber(io.read())\n","tests":[{"stdin":"4","out":"чёт"},{"stdin":"7","out":"нечет"}],"hint":"<code>n % 2 == 0</code>","solution":"local n = tonumber(io.read())\nif n % 2 == 0 then print(\"чёт\") else print(\"нечет\") end","explain":"if можно писать в одну строку."}]}]},{"id":"lua-u4","title":"Раздел 4. Циклы","lessons":[{"id":"lua-l10","title":"Цикл for","emoji":"🔁","intro":"<code>for i = 1, 5 do ... end</code> — i от 1 до 5 <b>включительно</b>. Третье число — шаг: <code>for i = 10, 1, -1 do</code> — обратный отсчёт. <code>for i = 0, 10, 2</code> — чётные.","questions":[{"type":"output","q":"Сколько раз выполнится цикл?","code":"for i = 1, 5 do\n  print(i)\nend","options":["5","4","6","1"],"explain":"1, 2, 3, 4, 5 — конец включается."},{"type":"output","q":"Какое число выведется последним?","code":"for i = 10, 1, -3 do\n  print(i)\nend","options":["1","4","10","0"],"explain":"10, 7, 4, 1."},{"type":"output","q":"Что выведет скрипт?","code":"local s = 0\nfor i = 1, 4 do s = s + i end\nprint(s)","options":["10","4","24","9"],"explain":"1+2+3+4 = 10. В Lua нет +=, пишут s = s + i."},{"type":"bug","q":"Где ошибка?","code":"for i = 1, 3 do\n  print(i)","options":["Нет end","Нужен then","Нельзя i","Ошибки нет"],"explain":"Цикл закрывается end."},{"type":"output","q":"Сколько раз выполнится цикл?","code":"for i = 5, 1 do\n  print(i)\nend","options":["0","5","1","Бесконечно"],"explain":"Без шага −1 цикл от 5 до 1 не выполнится ни разу."},{"type":"input","q":"Допиши слово:","code":"for i = 1, 10 ___","answers":["do"],"explain":"for ... do ... end"}]},{"id":"lua-l11","title":"while и repeat","emoji":"⏳","intro":"<code>while условие do ... end</code> — пока условие верно. <code>repeat ... until условие</code> — повторять, <b>пока условие не станет верным</b>, выполняется хотя бы раз. В Roblox бесконечный цикл <code>while true do ... task.wait(1) end</code> обязательно с паузой!","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local n = 1\nwhile n < 20 do n = n * 2 end\nprint(n)","options":["32","16","20","64"],"explain":"1, 2, 4, 8, 16, 32."},{"type":"output","q":"Сколько раз выполнится тело?","code":"local x = 10\nrepeat\n  x = x + 1\nuntil x > 5","options":["1","0","5","Бесконечно"],"explain":"repeat выполняется хотя бы раз, потом x > 5 — стоп."},{"type":"choice","q":"Что будет в Roblox без task.wait в while true?","options":["Игра зависнет","Всё нормально","Цикл выполнится один раз","Ошибка синтаксиса"],"explain":"Скрипт не отдаёт управление — Studio подвиснет."},{"type":"output","q":"Что выведет скрипт? (сумма цифр)","code":"local n, s = 123, 0\nwhile n > 0 do\n  s = s + n % 10\n  n = n // 10\nend\nprint(s)","options":["6","123","3","0"],"explain":"3 + 2 + 1."},{"type":"choice","q":"Чем repeat...until отличается от while?","options":["Условие проверяется в конце и означает «стоп»","Ничем","repeat быстрее","until — это then"],"explain":"until — «до тех пор пока не»."},{"type":"input","q":"Слово, завершающее repeat-цикл","answers":["until"],"explain":"repeat ... until"}]},{"id":"lua-l12","title":"break и вложенные циклы","emoji":"⛔","intro":"<code>break</code> — выйти из цикла. В Lua нет <code>continue</code> — вместо него используют if. Цикл в цикле — например, сетка блоков: <code>for x = 1, 3 do for z = 1, 3 do ... end end</code>.","questions":[{"type":"output","q":"Какое число выведется последним?","code":"for i = 1, 10 do\n  if i == 4 then break end\n  print(i)\nend","options":["3","4","10","1"],"explain":"На 4 вышли до вывода."},{"type":"output","q":"Сколько раз выполнится print?","code":"for x = 1, 3 do\n  for z = 1, 4 do\n    print(x, z)\n  end\nend","options":["12","7","3","4"],"explain":"3 × 4 — как сетка из 12 блоков."},{"type":"choice","q":"Есть ли continue в обычном Lua?","options":["Нет (в Luau от Roblox — есть)","Да","Только в while","Только в for"],"explain":"Roblox добавил continue в свой Luau, но в обычном Lua его нет."},{"type":"output","q":"Какие числа выведет?","code":"for i = 1, 5 do\n  if i % 2 == 1 then print(i) end\nend","options":["1 3 5","2 4","1 2 3 4 5","5"],"explain":"Только нечётные."},{"type":"output","q":"Что выведет скрипт?","code":"local found = nil\nfor i = 1, 100 do\n  if i * i > 50 then found = i break end\nend\nprint(found)","options":["8","7","50","nil"],"explain":"7·7 = 49, 8·8 = 64 > 50."},{"type":"input","q":"Команда выхода из цикла","answers":["break"],"explain":"break"}]},{"id":"lua-p4","title":"Практика: циклы","emoji":"💻","intro":"Повторяем действия циклами.","questions":[{"type":"code","q":"Обратный отсчёт","task":"Скрипт получает n. Выведи числа от n до 1 и потом <code>GO!</code>","starter":"local n = tonumber(io.read())\n","tests":[{"stdin":"3","out":"3\n2\n1\nGO!"}],"hint":"<code>for i = n, 1, -1 do</code>","solution":"local n = tonumber(io.read())\nfor i = n, 1, -1 do\n  print(i)\nend\nprint(\"GO!\")","explain":"Так начинаются раунды в играх."},{"type":"code","q":"Таблица умножения","task":"Скрипт получает число n. Выведи 5 строк вида <code>n x i = результат</code> для i от 1 до 5.","starter":"local n = tonumber(io.read())\n","tests":[{"stdin":"3","out":"3 x 1 = 3\n3 x 2 = 6\n3 x 3 = 9\n3 x 4 = 12\n3 x 5 = 15"}],"hint":"<code>print(n .. \" x \" .. i .. \" = \" .. n * i)</code>","solution":"local n = tonumber(io.read())\nfor i = 1, 5 do\n  print(n .. \" x \" .. i .. \" = \" .. n * i)\nend","explain":"Склейка чисел и строк."},{"type":"code","q":"Копилка","task":"Каждый раунд игрок получает 15 монет. Скрипт получает цель (число монет). Выведи, сколько раундов нужно, чтобы накопить не меньше цели.","starter":"local goal = tonumber(io.read())\n","tests":[{"stdin":"100","out":"7"},{"stdin":"15","out":"1"},{"stdin":"0","out":"0"}],"hint":"while coins &lt; goal do — добавляй 15 и считай раунды.","solution":"local goal = tonumber(io.read())\nlocal coins, rounds = 0, 0\nwhile coins < goal do\n  coins = coins + 15\n  rounds = rounds + 1\nend\nprint(rounds)","explain":"while — когда число повторов заранее неизвестно."}]}]},{"id":"lua-u5","title":"Раздел 5. Таблицы-списки","lessons":[{"id":"lua-l13","title":"Таблица как список","emoji":"📚","intro":"В Lua всё хранят в <b>таблицах</b>: <code>local items = {\"меч\", \"щит\", \"зелье\"}</code>. Нумерация с 1: <code>items[1]</code> — меч. Количество — <code>#items</code>. Добавить — <code>table.insert(items, \"лук\")</code>, убрать — <code>table.remove(items, 1)</code>.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local items = {\"меч\", \"щит\", \"зелье\"}\nprint(items[1])","options":["меч","щит","nil","зелье"],"explain":"В Lua первый элемент — номер 1."},{"type":"output","q":"Что выведет скрипт?","code":"local t = {5, 8, 2}\ntable.insert(t, 10)\nprint(#t)","options":["4","3","10","5"],"explain":"Добавили — стало 4."},{"type":"output","q":"Что выведет скрипт?","code":"local t = {1, 2, 3}\nprint(t[0])","options":["nil","1","Ошибку","0"],"explain":"Элемента 0 нет."},{"type":"output","q":"Что выведет скрипт?","code":"local t = {\"a\", \"b\", \"c\"}\ntable.remove(t, 1)\nprint(t[1], #t)","options":["b 2","a 2","b 3","nil 2"],"explain":"Остальные сдвинулись."},{"type":"output","q":"Что выведет скрипт?","code":"local t = {10, 20, 30}\nprint(t[#t])","options":["30","3","10","nil"],"explain":"t[#t] — последний элемент."},{"type":"input","q":"Функция добавления элемента: table.___","answers":["insert"],"explain":"table.insert"}]},{"id":"lua-l14","title":"Перебор: ipairs","emoji":"🔄","intro":"<code>for i, v in ipairs(t) do ... end</code> — перебирает список по порядку: i — номер, v — значение. Если номер не нужен — пишут <code>_</code>: <code>for _, v in ipairs(t)</code>. Склеить список — <code>table.concat(t, \", \")</code>.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local s = 0\nfor _, v in ipairs({3, 4, 5}) do s = s + v end\nprint(s)","options":["12","345","6","3"],"explain":"3 + 4 + 5."},{"type":"output","q":"Что выведет скрипт?","code":"print(table.concat({\"a\", \"b\", \"c\"}, \"-\"))","options":["a-b-c","abc","a, b, c","Ошибку"],"explain":"concat склеивает с разделителем."},{"type":"output","q":"Что выведет скрипт последней строкой?","code":"for i, v in ipairs({\"x\", \"y\"}) do\n  print(i .. \":\" .. v)\nend","options":["2:y","1:x","y:2","2"],"explain":"i — номер, v — значение."},{"type":"output","q":"Что выведет скрипт?","code":"local t = {7, 2, 9}\nlocal max = t[1]\nfor _, v in ipairs(t) do\n  if v > max then max = v end\nend\nprint(max)","options":["9","7","2","18"],"explain":"Поиск максимума."},{"type":"choice","q":"Что значит _ в for _, v in ipairs(t)?","options":["Переменная, которая нам не нужна","Ошибка","Пустая таблица","Номер 0"],"explain":"Так принято называть ненужные значения."},{"type":"input","q":"Функция для перебора списка по порядку","answers":["ipairs"],"explain":"ipairs"}]},{"id":"lua-l15","title":"Сортировка и math","emoji":"🧰","intro":"<code>table.sort(t)</code> — по возрастанию. Свой порядок — функцией: <code>table.sort(t, function(a, b) return a &gt; b end)</code> — по убыванию. <code>math.max(1, 5, 3)</code>, <code>math.min</code>, <code>math.floor</code>, <code>math.random(1, 6)</code> — кубик.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local t = {3, 1, 2}\ntable.sort(t)\nprint(table.concat(t, \" \"))","options":["1 2 3","3 2 1","3 1 2","Ошибку"],"explain":"По возрастанию."},{"type":"output","q":"Что выведет скрипт?","code":"local t = {3, 1, 2}\ntable.sort(t, function(a, b) return a > b end)\nprint(t[1])","options":["3","1","2","nil"],"explain":"По убыванию — первым стал 3."},{"type":"output","q":"Что выведет скрипт?","code":"print(math.max(4, 11, 7))","options":["11","4","7","22"],"explain":"Наибольшее."},{"type":"choice","q":"Что может вернуть math.random(1, 6)?","options":["Любое целое от 1 до 6","Только 1 или 6","Дробное число","Всегда 3"],"explain":"Как бросок кубика."},{"type":"output","q":"Что выведет скрипт?","code":"print(math.floor(4.9), math.abs(-3))","options":["4 3","5 3","4 -3","4.9 3"],"explain":"floor — вниз, abs — модуль."},{"type":"input","q":"Функция сортировки: table.___","answers":["sort"],"explain":"table.sort"}]},{"id":"lua-p5","title":"Практика: таблицы","emoji":"💻","intro":"Работаем с таблицами — главной структурой Lua.","questions":[{"type":"code","q":"Сумма очков","task":"Скрипт получает n, потом n чисел (по одному в строке). Выведи их сумму.","starter":"local n = tonumber(io.read())\n","tests":[{"stdin":"3\n10\n20\n5","out":"35"},{"stdin":"1\n7","out":"7"}],"hint":"Цикл for i = 1, n и tonumber(io.read()).","solution":"local n = tonumber(io.read())\nlocal s = 0\nfor i = 1, n do\n  s = s + tonumber(io.read())\nend\nprint(s)","explain":"Копилка в цикле."},{"type":"code","q":"Инвентарь наоборот","task":"Скрипт получает n, потом n предметов. Выведи их через запятую с пробелом в обратном порядке.","starter":"local n = tonumber(io.read())\nlocal inv = {}\n","tests":[{"stdin":"3\nмеч\nщит\nлук","out":"лук, щит, меч"}],"hint":"Сложи в таблицу через table.insert, потом цикл for i = #inv, 1, -1.","solution":"local n = tonumber(io.read())\nlocal inv = {}\nfor i = 1, n do\n  table.insert(inv, io.read())\nend\nlocal rev = {}\nfor i = #inv, 1, -1 do\n  table.insert(rev, inv[i])\nend\nprint(table.concat(rev, \", \"))","explain":"Новая таблица для перевёрнутого списка."},{"type":"code","q":"Рейтинг","task":"Скрипт получает n, потом n чисел очков. Выведи их по убыванию через пробел.","starter":"local n = tonumber(io.read())\nlocal t = {}\n","tests":[{"stdin":"4\n50\n90\n10\n70","out":"90 70 50 10"}],"hint":"table.sort с функцией <code>a &gt; b</code>, потом table.concat.","solution":"local n = tonumber(io.read())\nlocal t = {}\nfor i = 1, n do\n  table.insert(t, tonumber(io.read()))\nend\ntable.sort(t, function(a, b) return a > b end)\nprint(table.concat(t, \" \"))","explain":"Так строится таблица лидеров."}]}]},{"id":"lua-u6","title":"Раздел 6. Функции","lessons":[{"id":"lua-l16","title":"function и return","emoji":"🧱","intro":"<code>local function heal(hp, amount) return hp + amount end</code>. Вызов: <code>heal(50, 20)</code>. <code>return</code> возвращает результат. Функцию надо объявить <b>выше</b> места, где её вызывают.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local function double(x)\n  return x * 2\nend\nprint(double(7))","options":["14","7","72","nil"],"explain":"7 * 2."},{"type":"output","q":"Что выведет скрипт?","code":"local function f() end\nprint(f())","options":["ничего (пустая строка)","nil","0","Ошибку"],"explain":"Функция без return ничего не возвращает — print печатает пустую строку."},{"type":"output","q":"Что выведет скрипт?","code":"local function sum(a, b) return a + b end\nprint(sum(2, 3) * sum(1, 1))","options":["10","7","5","23"],"explain":"5 * 2."},{"type":"bug","q":"Почему ошибка?","code":"print(greet(\"Яр\"))\nlocal function greet(n) return \"Hi \" .. n end","options":["Функция вызвана раньше, чем объявлена","Нельзя ..","Нет then","Ошибки нет"],"explain":"Скрипт выполняется сверху вниз."},{"type":"output","q":"Что выведет скрипт?","code":"local function hi(name)\n  name = name or \"друг\"\n  return \"Привет, \" .. name\nend\nprint(hi())","options":["Привет, друг","Привет, nil","Ошибку","Привет, "],"explain":"Не передали аргумент — он nil, сработал or."},{"type":"input","q":"Слово для возврата результата","answers":["return"],"explain":"return"}]},{"id":"lua-l17","title":"Несколько результатов","emoji":"🎁","intro":"Функция в Lua может вернуть сразу несколько значений: <code>return min, max</code>, а получить их — <code>local a, b = f()</code>. Функция — это значение: её можно положить в переменную или передать в другую функцию.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local function mm(a, b)\n  if a < b then return a, b end\n  return b, a\nend\nlocal lo, hi = mm(9, 4)\nprint(lo)","options":["4","9","4 9","nil"],"explain":"Вернулись два значения: 4 и 9."},{"type":"output","q":"Что выведет скрипт?","code":"local function apply(f, x) return f(x) end\nprint(apply(function(n) return n + 100 end, 1))","options":["101","1","100","Ошибку"],"explain":"Функцию передали как аргумент."},{"type":"output","q":"Что выведет скрипт?","code":"local sq = function(x) return x * x end\nprint(sq(5))","options":["25","10","55","nil"],"explain":"Функция в переменной."},{"type":"choice","q":"Как в Roblox передают функцию в событие?","options":["part.Touched:Connect(function(hit) ... end)","part.Touched = hit","Connect(part)","Никак"],"explain":"Это та же передача функции как значения!"},{"type":"output","q":"Что выведет скрипт?","code":"local a, b, c = (function() return 1, 2 end)()\nprint(c)","options":["nil","2","1","Ошибку"],"explain":"Третьего значения нет — nil."},{"type":"input","q":"Допиши, чтобы вернуть два значения:","code":"return a___ b","answers":[","],"explain":"return a, b"}]},{"id":"lua-l18","title":"Замыкания и pcall","emoji":"🔒","intro":"Функция помнит переменные, рядом с которыми создана — это <b>замыкание</b>. Так делают счётчики. <code>pcall(f)</code> запускает функцию «безопасно»: при ошибке скрипт не падает, а pcall возвращает <code>false</code> и текст ошибки.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local function counter()\n  local n = 0\n  return function() n = n + 1 return n end\nend\nlocal c = counter()\nc() c()\nprint(c())","options":["3","1","0","nil"],"explain":"n живёт внутри замыкания и растёт."},{"type":"output","q":"Что выведет скрипт?","code":"local ok = pcall(function() error(\"бум\") end)\nprint(ok)","options":["false","true","бум","Скрипт упадёт"],"explain":"pcall поймал ошибку."},{"type":"output","q":"Что выведет скрипт?","code":"local ok, v = pcall(function() return 42 end)\nprint(ok, v)","options":["true 42","false 42","42","true"],"explain":"Без ошибки: true и результат."},{"type":"choice","q":"Зачем в Roblox pcall?","options":["Для операций, которые могут сорваться: DataStore, HTTP","Для ускорения","Для рисования","Не нужен"],"explain":"Сервер сохранения может быть недоступен — игра не должна падать."},{"type":"choice","q":"Как бросить свою ошибку?","options":["error(\"текст\")","throw \"текст\"","raise(\"текст\")","fail()"],"explain":"error — функция Lua."},{"type":"input","q":"Функция безопасного вызова","answers":["pcall"],"explain":"protected call"}]},{"id":"lua-p6","title":"Практика: функции","emoji":"💻","intro":"Пишем свои функции.","questions":[{"type":"code","q":"Урон с бронёй","task":"Напиши функцию <code>damage(attack, armor)</code>: урон = attack − armor, но не меньше 0. Скрипт читает два числа и выводит урон.","starter":"local function damage(attack, armor)\nend\nlocal a = tonumber(io.read())\nlocal b = tonumber(io.read())\nprint(damage(a, b))\n","tests":[{"stdin":"30\n10","out":"20"},{"stdin":"5\n10","out":"0"}],"hint":"<code>return math.max(0, attack - armor)</code>","solution":"local function damage(attack, armor)\n  return math.max(0, attack - armor)\nend\nlocal a = tonumber(io.read())\nlocal b = tonumber(io.read())\nprint(damage(a, b))","explain":"Броня не должна лечить :)"},{"type":"code","q":"Мин и макс","task":"Функция <code>minmax(t)</code> возвращает два значения: наименьшее и наибольшее в таблице. Скрипт читает числа через пробел и выводит <code>мин макс</code>.","starter":"local function minmax(t)\nend\nlocal t = {}\nfor x in io.read():gmatch(\"%S+\") do table.insert(t, tonumber(x)) end\nlocal lo, hi = minmax(t)\nprint(lo .. \" \" .. hi)\n","tests":[{"stdin":"5 2 9 1","out":"1 9"},{"stdin":"7","out":"7 7"}],"hint":"Начни с t[1], пройди ipairs. В конце <code>return lo, hi</code>.","solution":"local function minmax(t)\n  local lo, hi = t[1], t[1]\n  for _, v in ipairs(t) do\n    if v < lo then lo = v end\n    if v > hi then hi = v end\n  end\n  return lo, hi\nend\nlocal t = {}\nfor x in io.read():gmatch(\"%S+\") do table.insert(t, tonumber(x)) end\nlocal lo, hi = minmax(t)\nprint(lo .. \" \" .. hi)","explain":"gmatch(\"%S+\") разбивает строку на слова."},{"type":"code","q":"Счётчик кликов","task":"Сделай функцию <code>makeCounter()</code>, которая возвращает функцию-счётчик (каждый вызов +1 и возвращает число). Скрипт читает n, вызывает счётчик n раз и печатает последнее значение.","starter":"local function makeCounter()\nend\nlocal click = makeCounter()\nlocal n = tonumber(io.read())\nlocal last = 0\nfor i = 1, n do last = click() end\nprint(last)\n","tests":[{"stdin":"5","out":"5"},{"stdin":"1","out":"1"}],"hint":"Внутри: <code>local c = 0; return function() c = c + 1 return c end</code>","solution":"local function makeCounter()\n  local c = 0\n  return function()\n    c = c + 1\n    return c\n  end\nend\nlocal click = makeCounter()\nlocal n = tonumber(io.read())\nlocal last = 0\nfor i = 1, n do last = click() end\nprint(last)","explain":"Замыкание хранит своё состояние."}]}]},{"id":"lua-u7","title":"Раздел 7. Словари и объекты","lessons":[{"id":"lua-l19","title":"Таблица-словарь","emoji":"🗂️","intro":"Таблица с ключами: <code>local hero = {name = \"Яр\", hp = 100}</code>. Доступ: <code>hero.name</code> или <code>hero[\"name\"]</code>. Добавить: <code>hero.level = 5</code>, удалить: <code>hero.level = nil</code>. Перебрать все пары — <code>for k, v in pairs(hero) do</code> (порядок не гарантирован).","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local hero = {name = \"Яр\", hp = 100}\nprint(hero.hp)","options":["100","hp","Яр","nil"],"explain":"Ключ hp."},{"type":"output","q":"Что выведет скрипт?","code":"local p = {}\np.coins = 5\np.coins = p.coins + 10\nprint(p.coins)","options":["15","5","10","nil"],"explain":"Добавили и изменили поле."},{"type":"output","q":"Что выведет скрипт?","code":"local p = {x = 1}\nlocal key = \"x\"\nprint(p[key])","options":["1","x","nil","key"],"explain":"Ключ из переменной — в квадратных скобках."},{"type":"choice","q":"Чем перебирать словарь?","options":["pairs","ipairs","for i = 1, #t","concat"],"explain":"ipairs — только для списков 1, 2, 3…"},{"type":"output","q":"Ловушка! Что выведет скрипт?","code":"local t = {a = 1, b = 2}\nprint(#t)","options":["0","2","nil","Ошибку"],"explain":"# считает только элементы списка с номерами 1, 2, 3…"},{"type":"input","q":"Функция перебора всех пар ключ–значение","answers":["pairs"],"explain":"pairs"}]},{"id":"lua-l20","title":"Методы и двоеточие","emoji":"🤖","intro":"Функция в таблице — метод. Двоеточие передаёт саму таблицу как <code>self</code>: <code>function Hero:hit(d) self.hp = self.hp - d end</code>, вызов <code>hero:hit(10)</code>. Это то же самое, что <code>hero.hit(hero, 10)</code>. В Roblox так вызывают почти всё: <code>part:Destroy()</code>.","questions":[{"type":"output","q":"Что выведет скрипт?","code":"local hero = {hp = 100}\nfunction hero:hit(d)\n  self.hp = self.hp - d\nend\nhero:hit(30)\nprint(hero.hp)","options":["70","100","30","nil"],"explain":"self — это hero."},{"type":"choice","q":"Что значит двоеточие в hero:hit(10)?","options":["Передать hero первым аргументом (self)","Это опечатка","Деление","Комментарий"],"explain":"hero:hit(10) = hero.hit(hero, 10)."},{"type":"bug","q":"Почему ошибка «attempt to index nil»?","code":"local hero = {hp = 100}\nfunction hero:hit(d) self.hp = self.hp - d end\nhero.hit(10)","options":["Вызвали через точку — self не передан","Нет end","Нельзя 10","Ошибки нет"],"explain":"Нужно hero:hit(10)."},{"type":"choice","q":"Как в Roblox удалить деталь?","options":["part:Destroy()","part.Destroy","delete part","Destroy(part) через точку"],"explain":"Методы объектов Roblox вызывают через двоеточие."},{"type":"output","q":"Что выведет скрипт?","code":"local c = {n = 0}\nfunction c:inc() self.n = self.n + 1 end\nc:inc() c:inc() c:inc()\nprint(c.n)","options":["3","1","0","nil"],"explain":"Три вызова."},{"type":"input","q":"Как внутри метода называется сама таблица?","answers":["self"],"explain":"self"}]},{"id":"lua-l21","title":"Классы через метатаблицы","emoji":"🏗️","intro":"В Lua нет слова class, классы делают так:\n<code>local Hero = {}\nHero.__index = Hero\nfunction Hero.new(name) local self = setmetatable({}, Hero) self.name = name self.hp = 100 return self end\nfunction Hero:hit(d) self.hp = self.hp - d end</code>\n<code>__index</code> говорит: «если поля нет у объекта — ищи в Hero». Так пишут модули в Roblox.","questions":[{"type":"choice","q":"Как создать объект по такому классу?","options":["Hero.new(\"Яр\")","new Hero(\"Яр\")","Hero(\"Яр\")","class Hero"],"explain":"Принято делать функцию new."},{"type":"choice","q":"Что делает setmetatable({}, Hero)?","options":["Связывает новую таблицу с классом Hero","Удаляет Hero","Копирует Hero","Ничего"],"explain":"Через метатаблицу объект получает методы класса."},{"type":"choice","q":"Зачем Hero.__index = Hero?","options":["Чтобы методы искались в Hero","Чтобы ускорить","Для красоты","Это обязательно для print"],"explain":"Объект сам методов не хранит — они в классе."},{"type":"output","q":"Что выведет скрипт?","code":"local A = {}\nA.__index = A\nfunction A.new() return setmetatable({v = 1}, A) end\nfunction A:get() return self.v * 10 end\nprint(A.new():get())","options":["10","1","nil","Ошибку"],"explain":"Метод get найден через __index."},{"type":"output","q":"Что выведет скрипт?","code":"local A = {}\nA.__index = A\nfunction A.new() return setmetatable({hp = 5}, A) end\nlocal a, b = A.new(), A.new()\na.hp = 1\nprint(b.hp)","options":["5","1","nil","6"],"explain":"У каждого объекта своя таблица."},{"type":"input","q":"Функция, задающая метатаблицу","answers":["setmetatable"],"explain":"setmetatable"}]},{"id":"lua-p7","title":"Практика: объекты","emoji":"💻","intro":"Описываем игроков и предметы таблицами.","questions":[{"type":"code","q":"Магазин","task":"В таблице <code>prices</code> цены предметов. Скрипт получает название предмета и выводит цену или <code>нет в продаже</code>.","starter":"local prices = {sword = 50, shield = 30, potion = 10}\nlocal item = io.read()\n","tests":[{"stdin":"sword","out":"50"},{"stdin":"bow","out":"нет в продаже"}],"hint":"<code>local p = prices[item]</code>, если p == nil — нет в продаже.","solution":"local prices = {sword = 50, shield = 30, potion = 10}\nlocal item = io.read()\nlocal p = prices[item]\nif p then print(p) else print(\"нет в продаже\") end","explain":"Словарь — быстрый поиск по ключу."},{"type":"code","q":"Класс Hero","task":"Допиши метод <code>Hero:hit(d)</code> — уменьшает hp, но не ниже 0. Скрипт создаёт героя с 100 hp, читает урон, бьёт и выводит hp.","starter":"local Hero = {}\nHero.__index = Hero\nfunction Hero.new() return setmetatable({hp = 100}, Hero) end\n-- допиши Hero:hit\nlocal h = Hero.new()\nh:hit(tonumber(io.read()))\nprint(h.hp)\n","tests":[{"stdin":"30","out":"70"},{"stdin":"500","out":"0"}],"hint":"<code>function Hero:hit(d) self.hp = math.max(0, self.hp - d) end</code>","solution":"local Hero = {}\nHero.__index = Hero\nfunction Hero.new() return setmetatable({hp = 100}, Hero) end\nfunction Hero:hit(d)\n  self.hp = math.max(0, self.hp - d)\nend\nlocal h = Hero.new()\nh:hit(tonumber(io.read()))\nprint(h.hp)","explain":"Это настоящий ООП в стиле Roblox-модулей."},{"type":"code","q":"Подсчёт предметов","task":"Скрипт получает предметы через пробел. Выведи, сколько раз встретился предмет <code>coin</code>.","starter":"local count = {}\nfor w in io.read():gmatch(\"%S+\") do\nend\n","tests":[{"stdin":"coin gem coin coin","out":"3"},{"stdin":"gem","out":"0"}],"hint":"<code>count[w] = (count[w] or 0) + 1</code>, в конце <code>print(count.coin or 0)</code>","solution":"local count = {}\nfor w in io.read():gmatch(\"%S+\") do\n  count[w] = (count[w] or 0) + 1\nend\nprint(count.coin or 0)","explain":"Словарь-счётчик."}]}]},{"id":"lua-u8","title":"Раздел 8. Roblox: объекты мира","lessons":[{"id":"lua-l22","title":"Explorer и workspace","emoji":"🌍","intro":"В Roblox Studio всё — <b>объекты</b> (Instance) в дереве <b>Explorer</b>. <code>workspace</code> — всё, что в 3D-мире. <code>game.Players</code> — игроки, <code>ServerScriptService</code> — серверные скрипты, <code>ReplicatedStorage</code> — общее для сервера и клиента. Найти объект: <code>workspace.Lava</code> или <code>workspace:FindFirstChild(\"Lava\")</code>.","questions":[{"type":"choice","q":"Где хранятся все детали 3D-мира?","options":["workspace","Players","Lighting","StarterGui"],"explain":"workspace — это сама карта."},{"type":"choice","q":"Как безопасно найти объект, которого может не быть?","options":["workspace:FindFirstChild(\"Door\")","workspace.Door","find(Door)","workspace[\"?\"]"],"explain":"FindFirstChild вернёт nil, а workspace.Door — ошибку, если двери нет."},{"type":"choice","q":"Где обычно лежат серверные скрипты?","options":["ServerScriptService","StarterGui","workspace.Camera","Lighting"],"explain":"Код сервера игроки не видят."},{"type":"choice","q":"Как дождаться появления объекта?","options":["parent:WaitForChild(\"Name\")","wait(\"Name\")","parent.Name()","sleep()"],"explain":"Особенно важно в LocalScript — объекты грузятся не сразу."},{"type":"choice","q":"Как получить сервис Players?","options":["game:GetService(\"Players\")","Players.new()","workspace.Players","require(Players)"],"explain":"GetService — правильный способ получить любой сервис."},{"type":"input","q":"Главное 3D-пространство игры","answers":["workspace","Workspace"],"explain":"workspace"}]},{"id":"lua-l23","title":"Детали и свойства","emoji":"🧱","intro":"Создать деталь: <code>local p = Instance.new(\"Part\")</code>, настроить: <code>p.Size = Vector3.new(4, 1, 4)</code>, <code>p.Position = Vector3.new(0, 10, 0)</code>, <code>p.Color = Color3.fromRGB(255, 0, 0)</code>, <code>p.Anchored = true</code> (не падает), и положить в мир: <code>p.Parent = workspace</code>.","questions":[{"type":"choice","q":"Как создать новую деталь?","options":["Instance.new(\"Part\")","Part.new()","new Part()","workspace:Part()"],"explain":"Instance.new создаёт любой объект Roblox."},{"type":"choice","q":"Деталь создана, но её не видно. Почему?","options":["Не задан p.Parent = workspace","Нужно перезагрузить ПК","Деталь прозрачная всегда","Нужен print"],"explain":"Пока нет родителя — объект не в мире."},{"type":"choice","q":"Как сделать, чтобы деталь не падала?","options":["p.Anchored = true","p.Fall = false","p.Gravity = 0","p:Stop()"],"explain":"Anchored — «прибита» к месту."},{"type":"choice","q":"Чем задают позицию и размер?","options":["Vector3.new(x, y, z)","{x, y, z}","Position(1, 2, 3)","Size = 4"],"explain":"Vector3 — три координаты."},{"type":"choice","q":"Как сделать деталь красной?","options":["p.Color = Color3.fromRGB(255, 0, 0)","p.Color = \"red\"","p.Red = true","Color3(red)"],"explain":"RGB — красный, зелёный, синий от 0 до 255."},{"type":"choice","q":"Как сделать деталь полупрозрачной?","options":["p.Transparency = 0.5","p.Alpha = 50","p.Visible = 0.5","p.Glass = true"],"explain":"0 — непрозрачная, 1 — невидимая."}]},{"id":"lua-l24","title":"Script, LocalScript, ModuleScript","emoji":"📜","intro":"<b>Script</b> работает на сервере — для всех (монеты, урон, сохранения). <b>LocalScript</b> — на компьютере одного игрока (интерфейс, камера, клавиши). <b>ModuleScript</b> — общий код, подключается через <code>require(модуль)</code>. Правило: важные вещи решает только сервер — иначе читеры подменят.","questions":[{"type":"choice","q":"Где начислять монеты игроку?","options":["В Script на сервере","В LocalScript","В интерфейсе","Где угодно"],"explain":"Клиенту доверять нельзя — его можно взломать."},{"type":"choice","q":"Где обрабатывать нажатие клавиш игрока?","options":["В LocalScript","В Script на сервере","В ModuleScript без подключения","В workspace"],"explain":"Клавиатура есть только у клиента."},{"type":"choice","q":"Как подключить ModuleScript?","options":["local M = require(path.to.Module)","import Module","include Module","M = Module()"],"explain":"require возвращает то, что модуль сделал return."},{"type":"choice","q":"Что ModuleScript должен делать в конце?","options":["return таблицу с функциями","print","Ничего","wait()"],"explain":"local M = {} ... return M"},{"type":"choice","q":"Почему нельзя доверять клиенту?","options":["Читер может изменить свой клиент","Клиент медленный","Клиент без Lua","Можно доверять"],"explain":"Сервер — «судья», клиент — только просит."},{"type":"input","q":"Функция подключения модуля","answers":["require"],"explain":"require"}]},{"id":"lua-p8","title":"Практика: логика мира","emoji":"💻","intro":"Задачи на логику игр. Объектов Roblox в песочнице нет — тренируем чистый Lua, который потом пойдёт в Studio.","questions":[{"type":"code","q":"Цвет по команде","task":"Скрипт получает название команды: <code>red</code>, <code>blue</code> или другое. Выведи RGB-цвет: red — <code>255,0,0</code>, blue — <code>0,0,255</code>, иначе <code>128,128,128</code>.","starter":"local team = io.read()\nlocal colors = {red = {255, 0, 0}, blue = {0, 0, 255}}\n","tests":[{"stdin":"red","out":"255,0,0"},{"stdin":"green","out":"128,128,128"}],"hint":"<code>local c = colors[team] or {128, 128, 128}</code>, потом <code>table.concat(c, \",\")</code>","solution":"local team = io.read()\nlocal colors = {red = {255, 0, 0}, blue = {0, 0, 255}}\nlocal c = colors[team] or {128, 128, 128}\nprint(table.concat(c, \",\"))","explain":"Дальше в Studio: Color3.fromRGB(c[1], c[2], c[3])."},{"type":"code","q":"Лестница из блоков","task":"Скрипт получает число ступенек n. Для каждой выведи позицию блока <code>x,y,z</code>: x = i*4, y = i*2, z = 0 (i от 1 до n).","starter":"local n = tonumber(io.read())\n","tests":[{"stdin":"3","out":"4,2,0\n8,4,0\n12,6,0"}],"hint":"<code>print(i * 4 .. \",\" .. i * 2 .. \",0\")</code>","solution":"local n = tonumber(io.read())\nfor i = 1, n do\n  print(i * 4 .. \",\" .. i * 2 .. \",0\")\nend","explain":"В Studio вместо print: p.Position = Vector3.new(i * 4, i * 2, 0)."},{"type":"code","q":"Модуль утилит","task":"Сделай «модуль» — таблицу <code>Utils</code> с функцией <code>Utils.clamp(x, lo, hi)</code>, которая ограничивает x рамками. Скрипт читает x и выводит clamp(x, 0, 100).","starter":"local Utils = {}\n-- допиши Utils.clamp\nprint(Utils.clamp(tonumber(io.read()), 0, 100))\n","tests":[{"stdin":"150","out":"100"},{"stdin":"-5","out":"0"},{"stdin":"42","out":"42"}],"hint":"<code>return math.max(lo, math.min(hi, x))</code>","solution":"local Utils = {}\nfunction Utils.clamp(x, lo, hi)\n  return math.max(lo, math.min(hi, x))\nend\nprint(Utils.clamp(tonumber(io.read()), 0, 100))","explain":"В Studio это был бы ModuleScript с return Utils. (В Luau есть готовый math.clamp.)"}]}]},{"id":"lua-u9","title":"Раздел 9. Roblox: события и игроки","lessons":[{"id":"lua-l25","title":"Touched — касание","emoji":"👆","intro":"Событие срабатывает, когда что-то происходит. Подписка — <code>:Connect(функция)</code>:\n<code>lava.Touched:Connect(function(hit)\n  local hum = hit.Parent:FindFirstChild(\"Humanoid\")\n  if hum then hum.Health = 0 end\nend)</code>\n<code>hit</code> — часть тела, которая коснулась, <code>hit.Parent</code> — персонаж.","questions":[{"type":"choice","q":"Как подписаться на касание детали?","options":["part.Touched:Connect(function(hit) ... end)","part.Touched = function","if part.Touched then","part:Touch()"],"explain":":Connect — подписка на событие."},{"type":"choice","q":"Что такое hit в обработчике Touched?","options":["Часть, которая коснулась (например, нога)","Сам игрок","Урон","Время"],"explain":"Персонаж — это hit.Parent."},{"type":"choice","q":"Как понять, что коснулся именно персонаж?","options":["У hit.Parent есть Humanoid","hit.Name == \"Player\"","hit == true","Никак"],"explain":"Humanoid есть только у персонажей."},{"type":"choice","q":"Как убить персонажа лавой?","options":["humanoid.Health = 0","humanoid:Kill()","hit:Destroy() всегда","player = nil"],"explain":"Здоровье 0 — персонаж погибает."},{"type":"choice","q":"Почему Touched для монеты срабатывает много раз?","options":["Каждая часть тела касается отдельно — нужен «дебаунс» (флаг)","Это баг Roblox","Монета плохая","Так и надо"],"explain":"Ставят флаг: если уже собрана — выходим."},{"type":"input","q":"Метод подписки на событие","code":"part.Touched:___(f)","answers":["Connect"],"explain":"Connect"}]},{"id":"lua-l26","title":"Игроки и leaderstats","emoji":"🏅","intro":"<code>Players.PlayerAdded:Connect(function(player) ... end)</code> — игрок зашёл. Таблица очков справа сверху — папка <code>leaderstats</code> внутри игрока:\n<code>local ls = Instance.new(\"Folder\") ls.Name = \"leaderstats\" ls.Parent = player\nlocal coins = Instance.new(\"IntValue\") coins.Name = \"Coins\" coins.Parent = ls</code>","questions":[{"type":"choice","q":"Какое событие срабатывает при входе игрока?","options":["Players.PlayerAdded","Players.Joined","workspace.Enter","game.Start"],"explain":"PlayerAdded передаёт объект player."},{"type":"choice","q":"Как должна называться папка для таблицы очков?","options":["leaderstats (строго так)","Leaderboard","stats","Любое имя"],"explain":"Roblox показывает только папку с этим именем."},{"type":"choice","q":"Какой объект хранит целое число очков?","options":["IntValue","Part","Folder","Script"],"explain":"Есть ещё NumberValue, StringValue, BoolValue."},{"type":"choice","q":"Как добавить игроку 10 монет?","options":["player.leaderstats.Coins.Value += 10","player.Coins = 10","Coins + 10","leaderstats(10)"],"explain":"Значение хранится в .Value. (В Luau есть +=.)"},{"type":"choice","q":"Как получить игрока по персонажу?","options":["Players:GetPlayerFromCharacter(character)","character.Player","hit.Player","Players[character]"],"explain":"Полезно в Touched: кто именно коснулся."},{"type":"input","q":"Свойство, где лежит число в IntValue","answers":["Value"],"explain":"coins.Value"}]},{"id":"lua-l27","title":"Кнопки, клики и сервер","emoji":"📡","intro":"<b>ClickDetector</b> внутри детали ловит клики: <code>cd.MouseClick:Connect(function(player) ... end)</code>. Клиент и сервер общаются через <b>RemoteEvent</b>: клиент <code>remote:FireServer(данные)</code>, сервер <code>remote.OnServerEvent:Connect(function(player, данные) ... end)</code>. Сервер всегда проверяет данные!","questions":[{"type":"choice","q":"Как сделать деталь, на которую можно кликнуть?","options":["Добавить в неё ClickDetector","part.Clickable = true","Добавить Button","Никак"],"explain":"ClickDetector.MouseClick передаёт игрока."},{"type":"choice","q":"Как LocalScript просит сервер что-то сделать?","options":["remote:FireServer(...)","server.call()","game:Send()","print на сервер"],"explain":"RemoteEvent — мост между клиентом и сервером."},{"type":"choice","q":"Какой первый аргумент получает OnServerEvent?","options":["player — кто отправил","данные","время","ничего"],"explain":"Roblox сам подставляет отправителя — его нельзя подделать."},{"type":"choice","q":"Клиент шлёт «дай мне 999999 монет». Что должен сделать сервер?","options":["Проверить, имеет ли игрок на это право","Выдать","Выдать половину","Выключить игру"],"explain":"Никогда не доверяй данным с клиента."},{"type":"choice","q":"Чем ждать в Roblox (вместо wait)?","options":["task.wait(секунды)","sleep()","pause()","delay = 1"],"explain":"task.wait — современная замена устаревшего wait."},{"type":"input","q":"Объект для связи клиента и сервера: Remote___","answers":["Event"],"explain":"RemoteEvent"}]},{"id":"lua-p9","title":"Практика: игровая логика","emoji":"💻","intro":"Логика игровых событий на чистом Lua.","questions":[{"type":"code","q":"Дебаунс монеты","task":"Монета собирается только один раз. Скрипт получает n касаний (имена игроков по строке, первая строка — n). Выведи имя того, кто собрал монету первым, а на остальные касания ничего не выводи.","starter":"local n = tonumber(io.read())\nlocal collected = false\n","tests":[{"stdin":"3\nЯр\nЯр\nАня","out":"Яр"},{"stdin":"1\nМакс","out":"Макс"}],"hint":"В цикле: если <code>not collected</code> — печатаем и ставим <code>collected = true</code>. Читать io.read() нужно на каждом шаге.","solution":"local n = tonumber(io.read())\nlocal collected = false\nfor i = 1, n do\n  local who = io.read()\n  if not collected then\n    collected = true\n    print(who)\n  end\nend","explain":"Тот же флаг используют в Touched."},{"type":"code","q":"Таблица лидеров","task":"Первая строка n, потом n строк <code>имя монеты</code>. Выведи имя игрока с наибольшим числом монет.","starter":"local n = tonumber(io.read())\n","tests":[{"stdin":"3\nЯр 50\nАня 90\nМакс 70","out":"Аня"}],"hint":"Разбор строки: <code>local name, c = io.read():match(\"(%S+) (%d+)\")</code>","solution":"local n = tonumber(io.read())\nlocal best, bestC = nil, -1\nfor i = 1, n do\n  local name, c = io.read():match(\"(%S+) (%d+)\")\n  c = tonumber(c)\n  if c > bestC then best, bestC = name, c end\nend\nprint(best)","explain":"match с шаблоном достаёт кусочки строки."},{"type":"code","q":"Проверка покупки на сервере","task":"Сервер получает от клиента: монеты игрока, цену предмета. Выведи <code>куплено, осталось N</code>, если хватает, иначе <code>отказ</code>. Отрицательная цена — тоже <code>отказ</code> (читерство!).","starter":"local coins = tonumber(io.read())\nlocal price = tonumber(io.read())\n","tests":[{"stdin":"100\n30","out":"куплено, осталось 70"},{"stdin":"10\n30","out":"отказ"},{"stdin":"10\n-500","out":"отказ"}],"hint":"<code>if price &gt; 0 and coins &gt;= price then</code>","solution":"local coins = tonumber(io.read())\nlocal price = tonumber(io.read())\nif price > 0 and coins >= price then\n  print(\"куплено, осталось \" .. coins - price)\nelse\n  print(\"отказ\")\nend","explain":"Сервер проверяет всё — так защищаются от читеров."}]}]},{"id":"lua-u10","title":"Раздел 10. Сохранения, анимации и своя игра","lessons":[{"id":"lua-l28","title":"DataStore — сохранения","emoji":"💾","intro":"Чтобы монеты сохранялись между входами, используют <b>DataStoreService</b>:\n<code>local store = game:GetService(\"DataStoreService\"):GetDataStore(\"Coins\")\nlocal ok, data = pcall(function() return store:GetAsync(player.UserId) end)</code>\nСохранение — <code>SetAsync</code> при выходе (<code>PlayerRemoving</code>). Всегда через pcall!","questions":[{"type":"choice","q":"Какой сервис сохраняет данные игроков?","options":["DataStoreService","SaveService","Lighting","Players"],"explain":"Данные хранятся на серверах Roblox."},{"type":"choice","q":"Каким ключом лучше сохранять данные игрока?","options":["player.UserId","player.Name","Случайным числом","Временем"],"explain":"Имя можно поменять, а UserId — нет."},{"type":"choice","q":"Зачем pcall вокруг GetAsync?","options":["Запрос к серверу может не пройти — игра не упадёт","Для скорости","Без него не компилируется","Не нужен"],"explain":"Сеть и сервера иногда сбоят."},{"type":"choice","q":"Когда сохранять монеты игрока?","options":["При выходе (PlayerRemoving), и лучше ещё периодически","Никогда","Каждый кадр","Только при входе"],"explain":"Слишком частые сохранения Roblox ограничивает."},{"type":"choice","q":"Работает ли DataStore в Studio по умолчанию?","options":["Нужно включить доступ к API в настройках игры","Всегда","Никогда","Только на телефоне"],"explain":"Game Settings → Security → Enable Studio Access to API Services."},{"type":"input","q":"Метод загрузки данных: store:Get___","answers":["Async"],"explain":"GetAsync"}]},{"id":"lua-l29","title":"TweenService — плавные анимации","emoji":"🎞️","intro":"Плавно двигать, крутить, менять цвет — <b>TweenService</b>:\n<code>local TS = game:GetService(\"TweenService\")\nlocal info = TweenInfo.new(2)  -- 2 секунды\nTS:Create(door, info, {Position = door.Position + Vector3.new(0, 10, 0)}):Play()</code>","questions":[{"type":"choice","q":"Какой сервис делает плавные анимации свойств?","options":["TweenService","AnimationService","MoveService","RunService"],"explain":"Tween — «промежуточный» кадр."},{"type":"choice","q":"Что задаёт TweenInfo.new(2)?","options":["Длительность 2 секунды","2 повтора","Скорость 2","Размер 2"],"explain":"Ещё можно задать стиль, повторы и т. д."},{"type":"choice","q":"Как запустить созданный твин?","options":[":Play()",":Start()",":Run()","Он сам"],"explain":"TS:Create(...):Play()"},{"type":"choice","q":"Что передают третьим аргументом в Create?","options":["Таблицу целевых свойств","Имя детали","Время","Звук"],"explain":"{Position = ..., Color = ...}"},{"type":"choice","q":"Что такое RunService.Heartbeat?","options":["Событие каждый кадр","Пульс игрока","Звук","Сохранение"],"explain":"Для того, что обновляется постоянно."},{"type":"input","q":"Метод создания твина: TS:___(...)","answers":["Create"],"explain":"Create"}]},{"id":"lua-l30","title":"Своя игра: план","emoji":"🗺️","intro":"Как собрать свою игру (обби или симулятор): 1) карта из деталей; 2) leaderstats с монетами; 3) монеты/чекпоинты через Touched с дебаунсом; 4) магазин через RemoteEvent с проверкой на сервере; 5) DataStore для сохранений; 6) интерфейс в StarterGui через LocalScript; 7) тест с друзьями и публикация.","questions":[{"type":"choice","q":"Что сделать в первую очередь?","options":["Простую рабочую версию (карта + одна механика)","Сразу 100 уровней","Магазин доната","Рекламу"],"explain":"Сначала маленькая работающая игра, потом расширяем."},{"type":"choice","q":"Где делают интерфейс (кнопки, счётчики)?","options":["StarterGui + LocalScript","ServerScriptService","Lighting","workspace.Terrain"],"explain":"Интерфейс — у клиента."},{"type":"choice","q":"Как сделать чекпоинт в обби?","options":["SpawnLocation или запомнить последний коснувшийся блок","Сделать лаву","Через Lighting","Никак"],"explain":"Часто сохраняют номер этапа в leaderstats."},{"type":"choice","q":"Что важно перед публикацией?","options":["Проверить игру с другими игроками на ошибки и читы","Удалить все скрипты","Выключить сохранения","Ничего"],"explain":"Output в Studio покажет ошибки."},{"type":"choice","q":"Где смотреть ошибки скриптов?","options":["Окно Output в Studio","В Explorer","В Lighting","Нигде"],"explain":"View → Output."},{"type":"input","q":"Как называется игра-полоса препятствий в Roblox?","answers":["обби","obby"],"explain":"Obby — от obstacle course."}]},{"id":"lua-p10","title":"Финальный проект","emoji":"🏆","intro":"Финальные задачи курса Lua!","questions":[{"type":"code","q":"Симулятор кликов","task":"Каждый клик даёт монеты = 1 + уровень улучшения. Команды (первая строка n): <code>click</code> — клик, <code>upgrade</code> — купить улучшение за 10 монет (если хватает). В конце выведи <code>монеты уровень</code>.","starter":"local n = tonumber(io.read())\nlocal coins, level = 0, 0\n","tests":[{"stdin":"12\nclick\nclick\nclick\nclick\nclick\nclick\nclick\nclick\nclick\nclick\nupgrade\nclick","out":"2 1"},{"stdin":"2\nupgrade\nclick","out":"1 0"}],"hint":"click: <code>coins = coins + 1 + level</code>; upgrade: если coins &gt;= 10 — минус 10 и level + 1.","solution":"local n = tonumber(io.read())\nlocal coins, level = 0, 0\nfor i = 1, n do\n  local cmd = io.read()\n  if cmd == \"click\" then\n    coins = coins + 1 + level\n  elseif cmd == \"upgrade\" and coins >= 10 then\n    coins = coins - 10\n    level = level + 1\n  end\nend\nprint(coins .. \" \" .. level)","explain":"Ядро любого симулятора в Roblox!"},{"type":"code","q":"Обби: этапы","task":"Игрок касается чекпоинтов (первая строка n, далее номера этапов). Этап засчитывается, только если он ровно на 1 больше текущего (нельзя перепрыгнуть). Выведи итоговый этап (начало — 0).","starter":"local n = tonumber(io.read())\nlocal stage = 0\n","tests":[{"stdin":"5\n1\n2\n4\n3\n4","out":"4"},{"stdin":"2\n5\n1","out":"1"}],"hint":"<code>if s == stage + 1 then stage = s end</code>","solution":"local n = tonumber(io.read())\nlocal stage = 0\nfor i = 1, n do\n  local s = tonumber(io.read())\n  if s == stage + 1 then stage = s end\nend\nprint(stage)","explain":"Защита от «перепрыгивания» этапов."},{"type":"code","q":"Сохранение и загрузка","task":"Сымитируй DataStore таблицей. Команды (первая строка n): <code>save ИМЯ ЧИСЛО</code> и <code>load ИМЯ</code>. На load выведи сохранённое число или <code>0</code>, если сохранений нет.","starter":"local store = {}\nlocal n = tonumber(io.read())\n","tests":[{"stdin":"4\nsave yar 50\nload yar\nload anya\nsave yar 70","out":"50\n0"},{"stdin":"3\nsave a 1\nsave a 2\nload a","out":"2"}],"hint":"Разбор: <code>local cmd, name, val = io.read():match(\"(%S+) (%S+) ?(%d*)\")</code>","solution":"local store = {}\nlocal n = tonumber(io.read())\nfor i = 1, n do\n  local cmd, name, val = io.read():match(\"(%S+) (%S+) ?(%d*)\")\n  if cmd == \"save\" then\n    store[name] = tonumber(val)\n  else\n    print(store[name] or 0)\n  end\nend","explain":"Поздравляем — курс Lua для Roblox пройден! 🎮"}]}]}]}.units;
  const LESSONS = UNITS.flatMap(u => u.lessons.map(l => ({ ...l, unit: u.id })));
  const lessonById = id => LESSONS.find(l => l.id === id) || null;
  const lessonIndex = id => LESSONS.findIndex(l => l.id === id);
  const api = { lang: 'lua', UNITS, LESSONS, lessonById, lessonIndex };
  if (typeof module !== 'undefined' && module.exports) module.exports = api; else { root.COURSES = root.COURSES || {}; root.COURSES['lua'] = api; }
})(typeof self !== 'undefined' ? self : this);
